from __future__ import annotations
import json
from pathlib import Path
from config import DUCKDB_TEMP, HIRID_MAP_GLOB, HIRID_ROOT, RESULTS_DIR, SICDB_ROOT
import duckdb
ROOT = HIRID_ROOT
OUT = RESULTS_DIR
OUT.mkdir(parents=True, exist_ok=True)
PHARMA_GLOB = str(ROOT / 'raw_stage' / 'pharma_records' / 'csv' / 'part-*.csv').replace('\\', '/')
CSV_COLUMNS = "{patientid: 'INTEGER', pharmaid: 'INTEGER', givenat: 'TIMESTAMP', enteredentryat: 'TIMESTAMP', givendose: 'DOUBLE', cumulativedose: 'DOUBLE', fluidamount_calc: 'DOUBLE', cumulfluidamount_calc: 'DOUBLE', doseunit: 'VARCHAR', route: 'VARCHAR', infusionid: 'VARCHAR', typeid: 'INTEGER', subtypeid: 'DOUBLE', recordstatus: 'INTEGER'}"
MET = (1000605,)
PARA = (1000489, 1000490)
TARGET = MET + PARA
PRESSORS = (1000462, 1000656, 1000657, 1000658, 71, 1000750, 1000649, 1000650, 1000655, 112, 113)
SEDATIVE_BOLUS = (1000700, 1001054, 251, 1001052, 1000691, 1000239, 245, 390, 442, 1000400, 1000857)
BP_LOWERING = (1000763, 1001047, 1000252, 1000695, 1000867, 1000243, 1000868, 1001048, 1001141, 1001142, 117, 1000596, 1000436, 94, 242, 1000477)
con = duckdb.connect()
con.execute("SET memory_limit='768MB'")
con.execute('SET threads=2')
con.execute('SET preserve_insertion_order=false')
con.execute(f"SET temp_directory='{DUCKDB_TEMP.as_posix()}'")
con.execute(f"\n    CREATE TEMP TABLE target AS\n    SELECT ROW_NUMBER() OVER () AS target_id,\n           patientid::INTEGER AS patientid,\n           pharmaid::INTEGER AS pharmaid,\n           givenat::TIMESTAMP AS givenat,\n           route, givendose::DOUBLE AS givendose,\n           infusionid::VARCHAR AS infusionid\n    FROM read_csv('{PHARMA_GLOB}', union_by_name=true, header=true, columns={CSV_COLUMNS}, ignore_errors=true)\n    WHERE pharmaid IN {TARGET}\n      AND givenat IS NOT NULL\n      AND route IN ('iv-inj', 'iv-inf', 'cv-inj', 'cv-inf')\n      AND givendose > 0\n      AND (recordstatus & 2) = 0 AND (recordstatus & 32) = 0\n    ")
con.execute(f"\n    CREATE TEMP TABLE pressor_raw AS\n    SELECT patientid::INTEGER AS patientid, pharmaid::INTEGER AS pharmaid,\n           givenat::TIMESTAMP AS givenat, givendose::DOUBLE AS givendose,\n           infusionid::VARCHAR AS infusionid\n    FROM read_csv('{PHARMA_GLOB}', union_by_name=true, header=true, columns={CSV_COLUMNS}, ignore_errors=true)\n    WHERE pharmaid IN {PRESSORS}\n      AND patientid IN (SELECT DISTINCT patientid FROM target)\n      AND givenat IS NOT NULL AND givendose > 0\n      AND route IN ('cv-inf', 'iv-inf')\n      AND (recordstatus & 2) = 0 AND (recordstatus & 32) = 0\n    ")
con.execute('\n    CREATE TEMP TABLE pressor_intervals AS\n    WITH x AS (\n      SELECT *, LEAD(givenat) OVER (PARTITION BY patientid, infusionid ORDER BY givenat) AS next_at,\n                   LAG(givendose) OVER (PARTITION BY patientid, infusionid ORDER BY givenat) AS prev_dose\n      FROM pressor_raw\n    )\n    SELECT patientid, pharmaid, infusionid, givenat AS start_at,\n           CASE WHEN next_at IS NOT NULL AND next_at <= givenat + INTERVAL 15 MINUTE\n                THEN next_at ELSE givenat + INTERVAL 10 MINUTE END AS stop_at,\n           CASE WHEN prev_dose IS NOT NULL AND givendose <> prev_dose THEN 1 ELSE 0 END AS dose_change\n    FROM x\n    ')
con.execute('\n    CREATE TEMP TABLE pressor_state AS\n    SELECT t.target_id,\n           COUNT(DISTINCT p.infusionid) AS active_infusion_count\n    FROM target t LEFT JOIN pressor_intervals p\n      ON p.patientid=t.patientid AND p.start_at <= t.givenat AND t.givenat < p.stop_at\n    GROUP BY t.target_id\n    ')
con.execute('\n    CREATE TEMP TABLE pressor_changes AS\n    SELECT t.target_id,\n           MAX(CASE WHEN p.dose_change=1 THEN 1 ELSE 0 END) AS pressor_change_2h\n    FROM target t LEFT JOIN pressor_intervals p\n      ON p.patientid=t.patientid\n     AND p.start_at BETWEEN t.givenat - INTERVAL 2 HOUR AND t.givenat + INTERVAL 2 HOUR\n    GROUP BY t.target_id\n    ')
con.execute('\n    CREATE TEMP TABLE residual AS\n    SELECT t.target_id,\n           MAX(CASE WHEN o.givenat < t.givenat THEN 1 ELSE 0 END) AS other_drug_prev4h,\n           MAX(CASE WHEN o.givenat > t.givenat THEN 1 ELSE 0 END) AS other_drug_next2h\n    FROM target t LEFT JOIN target o\n      ON o.patientid=t.patientid AND o.pharmaid <> t.pharmaid\n     AND ((o.givenat >= t.givenat - INTERVAL 4 HOUR AND o.givenat < t.givenat)\n       OR (o.givenat > t.givenat AND o.givenat <= t.givenat + INTERVAL 2 HOUR))\n    GROUP BY t.target_id\n    ')
con.execute(f"\n    CREATE TEMP TABLE cointervention AS\n    SELECT t.target_id,\n           MAX(CASE WHEN p.pharmaid IN {SEDATIVE_BOLUS} THEN 1 ELSE 0 END) AS sedative_bolus_2h,\n           MAX(CASE WHEN p.pharmaid IN {BP_LOWERING} THEN 1 ELSE 0 END) AS bp_lowering_2h\n    FROM target t LEFT JOIN read_csv('{PHARMA_GLOB}', union_by_name=true, header=true, columns={CSV_COLUMNS}, ignore_errors=true) p\n      ON p.patientid::INTEGER=t.patientid\n     AND p.pharmaid::INTEGER NOT IN {TARGET}\n     AND p.givenat::TIMESTAMP BETWEEN t.givenat - INTERVAL 2 HOUR AND t.givenat + INTERVAL 2 HOUR\n     AND p.givendose::DOUBLE > 0\n     AND (p.recordstatus::INTEGER & 2) = 0 AND (p.recordstatus::INTEGER & 32) = 0\n     AND p.route IN ('iv-inj', 'iv-inf', 'cv-inj', 'cv-inf')\n    GROUP BY t.target_id\n    ")
con.execute("\n    CREATE TEMP TABLE annotated AS\n    SELECT t.*,\n           CASE WHEN t.pharmaid=1000605 THEN 'metamizole' ELSE 'paracetamol' END AS drug,\n           COALESCE(ps.active_infusion_count,0) > 0 AS pressor_active,\n           CASE WHEN COALESCE(r.other_drug_prev4h,0)=1 OR COALESCE(r.other_drug_next2h,0)=1 THEN 1 ELSE 0 END AS residual_excluded,\n           CASE WHEN COALESCE(pc.pressor_change_2h,0)=1 OR COALESCE(c.sedative_bolus_2h,0)=1 OR COALESCE(c.bp_lowering_2h,0)=1 THEN 1 ELSE 0 END AS cointervention_excluded,\n           COALESCE(r.other_drug_prev4h,0) AS other_drug_prev4h,\n           COALESCE(r.other_drug_next2h,0) AS other_drug_next2h,\n           COALESCE(c.sedative_bolus_2h,0) AS sedative_bolus_2h,\n           COALESCE(c.bp_lowering_2h,0) AS bp_lowering_2h,\n           COALESCE(pc.pressor_change_2h,0) AS pressor_change_2h,\n           CASE WHEN COALESCE(r.other_drug_prev4h,0)=0 AND COALESCE(r.other_drug_next2h,0)=0\n                     AND COALESCE(pc.pressor_change_2h,0)=0\n                     AND COALESCE(c.sedative_bolus_2h,0)=0\n                     AND COALESCE(c.bp_lowering_2h,0)=0 THEN 1 ELSE 0 END AS primary_keep\n    FROM target t\n    LEFT JOIN pressor_state ps ON ps.target_id=t.target_id\n    LEFT JOIN pressor_changes pc ON pc.target_id=t.target_id\n    LEFT JOIN residual r ON r.target_id=t.target_id\n    LEFT JOIN cointervention c ON c.target_id=t.target_id\n    ")
con.execute('\n    CREATE TEMP TABLE sequenced AS\n    SELECT a.*,\n           LAG(a.pharmaid) OVER (PARTITION BY a.patientid ORDER BY a.givenat, a.target_id) AS prev_pharmaid,\n           LAG(a.drug) OVER (PARTITION BY a.patientid ORDER BY a.givenat, a.target_id) AS prev_drug,\n           LAG(a.primary_keep) OVER (PARTITION BY a.patientid ORDER BY a.givenat, a.target_id) AS prev_primary_keep,\n           LAG(a.pressor_active) OVER (PARTITION BY a.patientid ORDER BY a.givenat, a.target_id) AS prev_pressor_active\n    FROM annotated a\n    ')
con.execute('\n    CREATE TEMP TABLE transitions AS\n    SELECT *\n    FROM sequenced\n    WHERE primary_keep=1 AND prev_primary_keep=1 AND prev_drug IS NOT NULL AND drug <> prev_drug\n    ')

def rows(sql: str):
    cur = con.execute(sql)
    cols = [d[0] for d in cur.description]
    return [dict(zip(cols, row)) for row in cur.fetchall()]
result = {'dataset': 'HiRID 1.1.1', 'definition': {'eligible': 'same target eligibility as frozen audit', 'strict_alternating_transition': 'current and immediately previous target administration in the patient timeline are different drugs; both administrations pass primary exclusions', 'previous_drug_covariate': 'prev_drug is retained for every transition', 'pressor_stratification': "current administration's reconstructed continuous pressor state", 'bidirectional_sequence': 'at least one metamizole->paracetamol and one paracetamol->metamizole retained transition in the same patient and pressor stratum'}, 'transition_counts': rows('\n        SELECT pressor_active, prev_drug, drug,\n               COUNT(*) AS transitions,\n               COUNT(DISTINCT patientid) AS patients\n        FROM transitions\n        GROUP BY ALL ORDER BY pressor_active, prev_drug, drug\n        '), 'patient_counts': rows("\n        WITH p AS (\n          SELECT patientid, pressor_active,\n                 COUNT(*) AS transitions,\n                 COUNT(*) FILTER (WHERE prev_drug='metamizole' AND drug='paracetamol') AS met_to_para,\n                 COUNT(*) FILTER (WHERE prev_drug='paracetamol' AND drug='metamizole') AS para_to_met,\n                 COUNT(*) FILTER (WHERE drug='metamizole') AS metamizole_current_events,\n                 COUNT(*) FILTER (WHERE drug='paracetamol') AS paracetamol_current_events\n          FROM transitions\n          GROUP BY patientid, pressor_active\n        )\n        SELECT pressor_active,\n               COUNT(*) FILTER (WHERE transitions>=1) AS patients_with_any_strict_transition,\n               COUNT(*) FILTER (WHERE met_to_para>=1 AND para_to_met>=1) AS patients_with_bidirectional_sequence,\n               SUM(transitions) FILTER (WHERE transitions>=1) AS strict_transition_events,\n               SUM(metamizole_current_events) FILTER (WHERE transitions>=1) AS metamizole_transition_events,\n               SUM(paracetamol_current_events) FILTER (WHERE transitions>=1) AS paracetamol_transition_events\n        FROM p\n        GROUP BY pressor_active ORDER BY pressor_active\n        "), 'reference_patient_counts': rows("\n        WITH s AS (\n          SELECT *, LAG(drug) OVER (PARTITION BY patientid ORDER BY givenat, target_id) AS prev_drug\n          FROM annotated\n        ), t AS (\n          SELECT * FROM s WHERE prev_drug IS NOT NULL AND drug<>prev_drug\n        ), p AS (\n          SELECT patientid, pressor_active,\n                 COUNT(*) AS transitions,\n                 COUNT(*) FILTER (WHERE prev_drug='metamizole' AND drug='paracetamol') AS met_to_para,\n                 COUNT(*) FILTER (WHERE prev_drug='paracetamol' AND drug='metamizole') AS para_to_met\n          FROM t\n          GROUP BY patientid, pressor_active\n        )\n        SELECT pressor_active,\n               COUNT(*) FILTER (WHERE transitions>=1) AS patients_with_any_strict_transition,\n               COUNT(*) FILTER (WHERE met_to_para>=1 AND para_to_met>=1) AS patients_with_bidirectional_sequence,\n               SUM(transitions) FILTER (WHERE transitions>=1) AS strict_transition_events\n        FROM p\n        GROUP BY pressor_active ORDER BY pressor_active\n        "), 'reference_unexcluded': rows('\n        WITH s AS (\n          SELECT *, LAG(pharmaid) OVER (PARTITION BY patientid ORDER BY givenat, target_id) AS prev_pharmaid,\n                    LAG(drug) OVER (PARTITION BY patientid ORDER BY givenat, target_id) AS prev_drug\n          FROM annotated\n        ), t AS (\n          SELECT * FROM s WHERE prev_drug IS NOT NULL AND drug<>prev_drug\n        )\n        SELECT pressor_active, prev_drug, drug, COUNT(*) AS transitions, COUNT(DISTINCT patientid) AS patients\n        FROM t GROUP BY ALL ORDER BY pressor_active, prev_drug, drug\n        ')}
(OUT / 'hirid_metamizole_crossover_sample_audit.json').write_text(json.dumps(result, indent=2, ensure_ascii=False), encoding='utf-8')
print(json.dumps(result, ensure_ascii=True, indent=2))
